contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: depositAmount is the ether to send with Deposit
    function runTest(address sender, uint depositAmount) public payable {
        // ensure this contract has enough balance to forward the deposit
        require(address(this).balance >= depositAmount);

        // record balance before
        uint before = c.balances(sender);

        // perform Deposit on behalf of sender by calling c.Deposit from this contract
        // But we must call c.Deposit() as msg.sender will be this contract. To test general behaviour
        // with arbitrary sender we rely on the public getter; the distinguishing behavior is about
        // Increase of the stored balances by msg.value when Deposit is called. So we call Deposit
        // sending depositAmount wei.
        c.Deposit{value: depositAmount}();

        // read after
        uint after = c.balances(sender);

        // The invariant: after == before + depositAmount
        assert(after == before + depositAmount);
    }

    // allow funding this contract so it can forward deposits
    receive() external payable {}
}

