import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor (actor), initialDeposit, collectAmount
    function testFuzz_property(address depositor, uint256 initialDeposit, uint256 collectAmount) public {
        // Keep values in wide, admissible domain
        vm.assume(depositor != address(0));
        // bound the deposit and collect to a reasonable max to avoid overflow in test env
        initialDeposit = bound(initialDeposit, 0, 1 ether);
        collectAmount = bound(collectAmount, 0, 1 ether);

        // 1) depositor deposits initialDeposit
        vm.deal(depositor, initialDeposit);
        vm.prank(depositor);
        c.Deposit{value: initialDeposit}();

        // record balance before collect
        uint256 before = c.balances(depositor);

        // 2) ensure MinSum is set to 0 so Collect only needs sufficient balance check
        // SetMinSum can only be called before Initialized(); call it from this test (deployer)
        c.SetMinSum(0);

        // 3) attempt Collect(collectAmount) as depositor; capture whether it succeeded
        bool ok;
        vm.prank(depositor);
        try c.Collect(collectAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // read balance after
        uint256 after = c.balances(depositor);

        // General rule expressed as a single assertion:
        // In the correct contract: if Collect succeeded, after = before - collectAmount; if Collect failed, after = before.
        // The reference satisfies this for all inputs; the mutant that made Deposit subtract can be driven
        // to violate this (the fuzzer will find such inputs where after != before - collectAmount when ok==true).
        if (ok) {
            assertTrue(after == before - collectAmount);
        } else {
            assertTrue(after == before);
        }
    }
}

