        c.SetLogFile(address(rl));

        // fund depositor and the reentrant log so nested deposits can send value if needed
        vm.deal(depositor, amount);
        // The reentrant log will forward zero-value nested Deposit, so no extra funds needed there

        // record balance before
        uint256 before = c.balances(depositor);

