// A reentrant Log: when AddMessage is called it immediately calls back into C.Deposit from the same external caller
contract ReentrantLog {
    C public target;
    constructor(address _t) { target = C(_t); }

    // mimic the signature of AddMessage
    function AddMessage(address _adr, uint _val, string memory) public {
        // attempt to reenter: call Deposit with zero value (can't send ETH from here)
        // but reentrancy can act on contract state; we do a harmless zero-value call
        // perform a low-level call to Deposit
        (bool s,) = address(target).call{value: 0}(abi.encodeWithSignature("Deposit()"));
        // ignore success/failure
        s;
    }

    // Allow receiving ETH so it can be set as log address without issues
    receive() external payable {}
}
